154: function pointToMap(clientX, clientY) {
155:   const r = canvas.getBoundingClientRect();
156:   const px = clientX - r.left;
157:   const py = clientY - r.top;
158:   return {
159:     px, py,
160:     nx: px / Math.max(1, r.width),
161:     ny: py / Math.max(1, r.height),
162:     inside: px >= 0 && py >= 0 && px <= r.width && py <= r.height,
163:   };
164: }
