166: let toastTimer = 0;
167: function toast(message, type = '') {
168:   const wrap = $('#toasts');
169:   const key = message + type;
170:   const now = performance.now();
171:   const existing = [...wrap.children].find(el => el.dataset.key === key);
172:   if (existing && now - toastTimer < 500) return;
173:   toastTimer = now;
174:   const el = document.createElement('div');
175:   el.className = `toast ${type}`;
176:   el.dataset.key = key;
177:   el.textContent = message;
178:   wrap.appendChild(el);
179:   while (wrap.children.length > 3) wrap.removeChild(wrap.firstChild);
180:   setTimeout(() => {
181:     el.classList.add('out');
182:     setTimeout(() => el.remove(), 320);
183:   }, 2600);
184: }
