227: function onCardDown(e, type, card) {
228:   if (e.button !== undefined && e.button !== 0) return;
229:   if (!game.started) return;
230:   if (game.phase === 'victory' || game.phase === 'defeat') return;
231:   e.preventDefault();
232:   audio.ensure();
233:   const def = TOWERS[type];
234:   if (game.credits < def.cost) {
235:     audio.error();
236:     toast(`Need ${def.cost - game.credits} more credits for ${def.short}`, 'bad');
237:     return;
238:   }
239:   drag = {
240:     type,
241:     card,
242:     startX: e.clientX,
243:     startY: e.clientY,
244:     moved: false,
245:     pointerId: e.pointerId,
246:     captured: false,
247:   };
248:   try {
249:     card.setPointerCapture(e.pointerId);
250:     drag.captured = true;
251:   } catch {}
252: }
