254: window.addEventListener('pointermove', (e) => {
255:   if (!drag) return;
256:   if (!drag.moved) {
257:     const dx = e.clientX - drag.startX;
258:     const dy = e.clientY - drag.startY;
259:     if (Math.hypot(dx, dy) < 7) return;
260:     drag.moved = true;
261:     audio.ensure();
262:     // close inspector + arm the tower
263:     closeInspector(true);
264:     if (selectedType) cancelPlacement(true);
265:     selectedType = drag.type;
266:     game.setPending(drag.type);
267:     setArmed(drag.type);
268:     drag.card.classList.add('dragging');
269:     dragGhost.innerHTML = `
270:       <span class="tower-icon">${TOWERS[drag.type].icon}</span>
271:       <span class="ghost-name">${TOWERS[drag.type].short}</span>
272:       <span class="ghost-cost">${COIN}${TOWERS[drag.type].cost}</span>`;
273:     dragGhost.classList.remove('hidden');
274:     dragGhost.classList.remove('bad');
275:     ghostVisible = true;
276:     audio.ui();
277:   }
278:   if (!drag.moved) return;
279:   dragGhost.style.left = `${e.clientX}px`;
280:   dragGhost.style.top = `${e.clientY}px`;
281:   const pos = pointToMap(e.clientX, e.clientY);
282:   if (pos.inside) {
283:     game.setPreview(pos.nx, pos.ny);
284:     const valid = game.preview?.valid ?? false;
285:     dragGhost.classList.toggle('bad', !valid);
286:     placeHint.classList.add('hidden');
287:   } else {
288:     game.setPreview(null);
289:     dragGhost.classList.remove('bad');
290:   }
291: });
