293: window.addEventListener('pointerup', (e) => {
294:   if (!drag) return;
295:   const d = drag;
296:   drag = null;
297:   try { if (d.captured && d.card.hasPointerCapture(d.pointerId)) d.card.releasePointerCapture(d.pointerId); } catch {}
298:   d.card.classList.remove('dragging');
299:   dragGhost.classList.add('hidden');
300:   ghostVisible = false;
301: 
302:   if (!d.moved) {
303:     // tap on the card → arm placement for the next map tap
304:     if (selectedType === d.type) {
305:       cancelPlacement();
306:     } else {
307:       closeInspector(true);
308:       game.setPending(d.type);
309:       selectedType = d.type;
310:       setArmed(d.type);
311:       audio.ui();
312:       toast(`Tap the sand to deploy ${TOWERS[d.type].short}`);
313:     }
314:     return;
315:   }
316: 
317:   const pos = pointToMap(e.clientX, e.clientY);
318:   let placed = false;
319:   let reason = '';
320:   if (pos.inside) {
321:     const res = game.placeTower(d.type, pos.nx, pos.ny);
322:     placed = res.ok;
323:     reason = res.reason;
324:   }
325:   game.setPending(null);
326:   game.setPreview(null);
327:   selectedType = null;
328:   setArmed(null);
329:   if (placed) {
330:     toast(`${TOWERS[d.type].name} deployed`, 'good');
331:   } else if (pos.inside && reason) {
332:     audio.error();
333:     toast(reason, 'bad');
334:   }
335:   syncUI(true);
336: });
