501: function syncIntel(h) {
502:   const activeMap = game.started ? game.map : selectedMap;
503:   const key = `${activeMap.id}:${game.started}:${h.wave}:${h.phase}`;
504:   if (key === lastIntelKey) return;
505:   lastIntelKey = key;
506:   const body = $('#intelBody');
507:   const threat = $('#intelThreat');
508:   const title = $('#intelTitle');
509:   if (!body) return;
510:   if (!game.started) {
511:     body.innerHTML = '<span class="intel-tip">Deploy the outpost to see enemy movements.</span>';
512:     threat.textContent = 'STANDBY';
513:     threat.className = 'threat';
514:     return;
515:   }
516:   if (h.phase === 'victory' || h.phase === 'defeat') {
517:     body.innerHTML = '<span class="intel-tip">Mission concluded. Redeploy for another run.</span>';
518:     threat.textContent = h.phase === 'victory' ? 'SECURED' : 'OFFLINE';
519:     threat.className = 'threat';
520:     return;
521:   }
522:   title.textContent = h.phase === 'wave' ? 'WAVE INTEL' : 'NEXT WAVE INTEL';
523:   const specs = makeWave(h.wave, activeMap.id);
524:   const counts = {};
525:   for (const s of specs) counts[s.type] = (counts[s.type] || 0) + 1;
526:   const roster = waveRoster(h.wave, activeMap.id);
527:   const order = [...new Set([roster.line, roster.fast, roster.heavy, roster.boss])];
528:   body.innerHTML = order
529:     .filter(t => counts[t])
530:     .map((t) => {
531:       const def = ENEMY_TYPES[t];
532:       return `<span class="intel-chip"><i class="enemy-dot ${def.boss ? 'boss' : ''}" style="--dotc:${def.color}"></i><b>${counts[t]}</b>${def.short}</span>`;
533:     })
534:     .join('');
535:   let level = 'LOW';
536:   const bossEvery = activeMap.bossEvery ?? 10;
537:   const bossWave = (bossEvery > 0 && h.wave % bossEvery === 0) || h.wave === activeMap.waves;
538:   if (h.wave > 18 || bossWave) level = 'EXTREME';
539:   else if (h.wave > 11) level = 'HIGH';
540:   else if (h.wave > 4) level = 'MODERATE';
541:   threat.textContent = `${level} THREAT`;
542:   threat.className = `threat ${level === 'MODERATE' ? 'moderate' : level === 'HIGH' ? 'high' : level === 'EXTREME' ? 'extreme' : ''}`;
543: }
